"""Apply the tested three-line keeper validation call."""
from pathlib import Path
import base64,hashlib,subprocess
raw=base64.b64decode('',validate=True)
assert hashlib.sha256(raw).hexdigest()=='dcdccee2b99fd6f367415cdb43694b9912510f35938884645da90666ac7fa7db'
p=Path('/tmp/keeper-call.patch');p.write_bytes(raw)
subprocess.run(['git','apply','--check',str(p)],check=True)
subprocess.run(['git','apply',str(p)],check=True)
